INSERT IGNORE INTO `cau_hinh_phien_ban` (`id`, `phien_ban`) VALUES (1, 1);
INSERT IGNORE INTO `cau_hinh_khoi_dong_lai` (`id`, `trang_thai`) VALUES (1, '');
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('che_do', 'Chế độ game', 'Bật/tắt các chế độ lớn. Hầu hết cần khởi động lại máy chủ (đổi bảng EXP, schema, nội dung).', 1);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('kinh_te', 'Kinh tế', 'Tỉ lệ rơi, EXP, thuế chợ, phí, ngân sách giftcode. Áp dụng ngay.', 2);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('nap_tien', 'Nạp tiền', 'Công tắc bán từng loại sản phẩm, hoàn tiền, trần chi tiêu. Web vẫn KHOÁ (fail closed) khi thiếu HTBB_NAP_BAT, giấy phép hoặc bí mật cổng thanh toán — các giá trị đó nằm trong biến môi trường, không ở CSDL.', 3);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('thanh_vien', 'Thành viên', 'Thành viên HTBB theo tài khoản (trả phí) và Kích hoạt tài khoản (miễn phí): tính năng bị khoá, giá, thời hạn, chặn đăng nhập.', 4);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('dang_ky', 'Đăng ký', 'Đăng ký trong game / trên web, giới hạn Pokémon.', 5);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('su_kien', 'Sự kiện', 'Lịch hẹn sự kiện, World Cup, chiếm Gym. Bật/tắt từng sự kiện ở trang Sự kiện (bảng tob_su_kien).', 6);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('bao_tri', 'Bảo trì', 'Giờ bảo trì hằng ngày, chế độ bảo trì đăng nhập, danh sách được vào khi bảo trì.', 7);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('chong_spam', 'Chống spam, DoS & nhật ký', 'Nhịp chat/thao tác, chống ngập kết nối/gói tin, mức nhật ký.', 8);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('pvp', 'PvP / Gym / Hầm Ngục', 'Công tắc nội dung chiến đấu thiết kế dài hạn (chỉ có tác dụng khi sv.lau_dai=1).', 9);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('chi_so', 'Chỉ số & chống lạm phát', 'Trần + giảm dần cho chỉ số trang bị, pet, thú cưỡi, skin (docs/thiet-ke-game.md). Chỉ có tác dụng khi sv.lau_dai=1. Áp dụng ngay (đòn kế tiếp; kẹp đồ: lần mặc/tháo kế tiếp).', 10);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('tu_dong', 'Tự động đánh', 'Tự động đánh chính thức (chỉ khi online, theo luật năng lượng như đánh tay; vé treo máy offline tách riêng). Áp dụng ngay.', 11);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('hoi_sinh', 'Hồi sinh', 'Khi Pokémon gục: hồi sinh tại chỗ (vật phẩm / xu theo cấp / lượng khoá, có chờ + hồi chiêu, cấm ở PvP / Gym / boss / Mê cung), về Trung tâm Pokémon (miễn phí, phạt nhẹ: EXP cấp, độ bền, Mệt mỏi) hoặc chờ đồng đội. Áp dụng ngay.', 12);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('thong_bao', 'Thông báo', 'Gộp thông báo toàn máy chủ, địa chỉ website / link tải hiện trong game.', 13);
INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`) VALUES ('quan_tri', 'Quản trị & thử nghiệm', 'Danh sách GM, chế độ thử. Các khoá thử nghiệm bị khoá ở máy thật.', 14);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`) VALUES ('sv.lau_dai', 'che_do', 'Thiết kế dài hạn', '1 = bật GD2 (bảng EXP mới, chuyển EXP Pokémon một lần có sao lưu). Bật/tắt chạy chuyển đổi EXP lúc khởi động.', 'co', '0', '{}', 'khoi_dong_lai', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.LauDai / real.ChuyenDoiLauDai', 1);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`) VALUES ('sv.he_sinh_thai', 'che_do', 'Hệ sinh thái', '1 = bật hệ sinh thái thế giới (data_hst_*, tob_hst_*).', 'co', '0', '{}', 'khoi_dong_lai', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.HeSinhThai', 2);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`) VALUES ('sv.tran_cap_theo_mua', 'che_do', 'Trần cấp theo mùa', '1 = bật lại trần cấp 60→100 theo ngày khai trương (thiết kế cũ). 0 = không trần, lên cấp chậm + vật phẩm tăng tốc.', 'co', '0', '{}', 'khoi_dong_lai', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.LauDai#tranTheoMua', 3);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`) VALUES ('sv.ngay_khai_truong', 'che_do', 'Ngày khai trương', 'yyyy-MM-dd — ngày 0 của lịch mùa. Để trống = theo lau_dai.ngay_khai_truong game tự ghi.', 'ngay', '', '{}', 'khoi_dong_lai', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.LauDai#datNgayKhaiTruong', 4);
