INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`) VALUES ('kich_hoat.chuc_nang', 'thanh_vien', 'Tính năng khoá khi chưa kích hoạt', 'Cùng cổng với Thành viên: bị chặn nếu (cần kích hoạt và chưa kích hoạt) hoặc (cần Thành viên và chưa là Thành viên).', 'ds_chuoi', 'giao_dich,chat_the_gioi,cho,chuyen_luong,nhan_tang,giftcode', '{"luaChon": ["giao_dich", "nhan_tang", "chat_the_gioi", "cho", "cho_sinh_thai", "chuyen_luong", "bang", "pvp_xep_hang", "giftcode", "qua_online", "gui_thu"], "luaChonTen": ["Giao d\\u1ecbch tr\\u1ef1c ti\\u1ebfp", "Nh\\u1eadn giao d\\u1ecbch / qu\\u00e0", "Chat th\\u1ebf gi\\u1edbi (loa)", "Ch\\u1ee3 k\\u00fd g\\u1eedi", "Ch\\u1ee3 sinh th\\u00e1i", "Chuy\\u1ec3n l\\u01b0\\u1ee3ng", "\\u0110\\u1ed9i", "Gi\\u1ea3i Li\\u00ean minh x\\u1ebfp h\\u1ea1ng", "Giftcode", "Qu\\u00e0 online", "Nh\\u1eafn tin ri\\u00eang / t\\u1eb7ng qu\\u00e0"]}', 'ngay', 0, 0, 0, 'cau_hinh', 'ca_hai', 'ThanhVienLogic.quyetDinh', 59);
